import itertools
from z3 import *

n_golfers = 18
n_groups = 6
group_size = 3
n_weeks = 7

# Variables: g[w][p] = group of golfer p in week w (0..5)
g = [[Int(f"g_{w}_{p}") for p in range(n_golfers)] for w in range(n_weeks)]

s = Solver()

# Each golfer assigned to a valid group
for w in range(n_weeks):
    for p in range(n_golfers):
        s.add(g[w][p] >= 0, g[w][p] < n_groups)

# Each week: exactly 3 golfers per group
for w in range(n_weeks):
    for grp in range(n_groups):
        # Count golfers in this group
        s.add(Sum([If(g[w][p] == grp, 1, 0) for p in range(n_golfers)]) == group_size)

# No pair repeats
# For each pair of golfers (i,j), they can be in same group at most once
for i in range(n_golfers):
    for j in range(i+1, n_golfers):
        # Sum over weeks of indicator that they are in same group
        same_group = [If(g[w][i] == g[w][j], 1, 0) for w in range(n_weeks)]
        s.add(Sum(same_group) <= 1)

print("Solving...")
result = s.check()
print("Result:", result)

if result == sat:
    m = s.model()
    schedule = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            schedule.append(m.evaluate(g[w][p]).as_long())
    print("Schedule:", schedule)

    # Verify
    for w in range(n_weeks):
        groups = {}
        for p in range(n_golfers):
            grp = schedule[w*18 + p]
            groups.setdefault(grp, []).append(p)
        print(f"Week {w}: {groups}")

    # Check pairs
    pairs_seen = set()
    for w in range(n_weeks):
        for grp in range(n_groups):
            members = [p for p in range(n_golfers) if schedule[w*18 + p] == grp]
            assert len(members) == 3
            for i in range(3):
                for j in range(i+1, 3):
                    pair = (min(members[i], members[j]), max(members[i], members[j]))
                    if pair in pairs_seen:
                        print(f"ERROR: pair {pair} repeats!")
                    pairs_seen.add(pair)
    print(f"Total unique pairs: {len(pairs_seen)}")
else:
    print("UNSAT")
